import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int atIndex = -1;
        for (int index = 1; index < inputStr.length() - 1; index++) {
            if (inputStr.charAt(index) == 'a' && inputStr.charAt(index + 1) == 't' && index + 1 != inputStr.length() - 1) {
                atIndex = index;
                break;
            }
        }
        System.out.print(inputStr.charAt(0));
        for (int i = 1; i < inputStr.length(); i++) {
            if (i + 2 < inputStr.length() && inputStr.charAt(i) == 'd' && inputStr.charAt(i + 1) == 'o' && inputStr.charAt(i + 2) == 't' && i + 2 != inputStr.length() - 1) {
                System.out.print('.');
                i += 2;
                continue;
            }
            if (i == atIndex) {
                System.out.print('@');
                i++;
                continue;
            }
            System.out.print(inputStr.charAt(i));
        }
        scanner.close();
    }
}
